('water', 'Zemplínská šírava', 'Přehradní nádrž. Vodní plocha na Slovensku — příjemný cíl vyjížďky s výhledy na hladinu.', 48.78333, 22.03667, 'SK', 'wikidata-cs-batch1', 30057, 'http://commons.wikimedia.org/wiki/Special:FilePath/Slovakia%20Zemplinska%20Sirava%2010.jpg', '{"en": {"name": "Zemplínska šírava", "description": "Reservoir in Slovakia. A body of water in Slovakia — a pleasant ride destination with waterside views."}, "de": {"name": "Zemplínska šírava", "description": "Stausee in der Slowakei. Ein Gewässer in der Slowakei — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Zbiornik Zempliński", "description": "Zbiornik retencyjny (Powiat Michalovce, Słowacja). Akwen na Słowacji — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Zemplínska šírava", "description": "Stuwmeer in Slowakije. Een waterpartij in Slowakije — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Zemplínská šírava", "description": "Una masa de agua en Eslovaquia: un destino agradable con vistas al agua."}, "fr": {"name": "Zemplínska šírava", "description": "Un plan d''eau en Slovaquie — une belle destination avec vue sur l''eau."}, "uk": {"name": "Земплінська Ширава", "description": "Водойма у Словаччині — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
